import React, { useState, useEffect } from 'react';
import './AdminPanel.css';  // Importing the CSS file for styling

const ForumForm = ({ onSubmit }) => {
    const [name, setName] = useState('');
    const [description, setDescription] = useState('');
    const [categories, setCategories] = useState([]);
    const [forums, setForums] = useState([]);
    const [selectedOption, setSelectedOption] = useState('');
    const [banner, setBanner] = useState('');
    const [error, setError] = useState(null);
    const [success, setSuccess] = useState(null);

    // Fetch categories and forums when the component mounts
    useEffect(() => {
        fetch('http://localhost:8741/api/categoy/list')
            .then(response => response.json())
            .then(data => setCategories(data))
            .catch(error => setError("Failed to load categories."));

        fetch('http://localhost:8741/api/forums')
            .then(response => response.json())
            .then(data => setForums(data))
            .catch(error => setError("Failed to load forums."));
    }, []);

    const handleSubmit = (e) => {
        e.preventDefault();

        if (!name || !description || !selectedOption) {
            setError("All fields are required.");
            return;
        }

        const isCategory = selectedOption.startsWith('category_');
        const payload = {
            name,
            description,
            banner,
            [isCategory ? 'category_id' : 'parent_forum_id']: selectedOption.split('_')[1],
        };

        onSubmit(payload)
            .then(() => {
                setSuccess("Forum or Subforum created successfully!");
                setName('');
                setDescription('');
                setSelectedOption('');
                setBanner('');
                setError(null);
            })
            .catch((err) => {
                setError("An error occurred while creating the forum or subforum.");
                setSuccess(null);
            });
    };

    return (
        <form onSubmit={handleSubmit} className="admin-panel-form">
            <h2>Create a New Forum or Subforum</h2>

            {error && <div className="error-message">{error}</div>}
            {success && <div className="success-message">{success}</div>}

            <label>
                Name:
                <input 
                    type="text" 
                    value={name} 
                    onChange={(e) => setName(e.target.value)} 
                    required 
                />
            </label>

            <label>
                Description:
                <textarea 
                    value={description} 
                    onChange={(e) => setDescription(e.target.value)} 
                    required 
                />
            </label>

            <label>
                Category or Parent Forum:
                <select 
                    value={selectedOption} 
                    onChange={(e) => setSelectedOption(e.target.value)} 
                    required
                >
                    <option value="" disabled>Select a category or parent forum</option>
                    {categories.map(category => (
                        <option key={`category_${category.id}`} value={`category_${category.id}`}>
                            {category.name} (Category)
                        </option>
                    ))}
                    {forums.map(forum => (
                        <option key={`forum_${forum.id}`} value={`forum_${forum.id}`}>
                            {forum.name} (Forum)
                        </option>
                    ))}
                </select>
            </label>

            <label>
                Banner URL:
                <input 
                    type="text" 
                    value={banner} 
                    onChange={(e) => setBanner(e.target.value)} 
                />
            </label>

            <button type="submit">Create</button>
        </form>
    );
};

export default ForumForm;
